mapper.select:
SELECT TASK_ID, ROUND_NO, BID_CASE_ID, OPENED_BY, OPENED_AT, RECIP_COUNT, CLOSED_AT, CLOSE_CD, CLOSED_BY
  FROM DESIGN_ROUND
 WHERE TASK_ID = #{taskId} AND ROUND_NO = #{roundNo}

mapper.update:
UPDATE DESIGN_ROUND
   SET CLOSED_AT = #{closedAt}, CLOSE_CD = #{closeCd}, CLOSED_BY = #{closedBy}
 WHERE TASK_ID = #{taskId} AND ROUND_NO = #{roundNo} AND CLOSED_AT IS NULL

mapper.select:
SELECT B.BID_CASE_ID, B.INSTITUTION_ID, I.NAME_KO AS INSTITUTION_NAME
  FROM BID_CASES B
  JOIN INSTITUTIONS I ON I.INSTITUTION_ID = B.INSTITUTION_ID
 WHERE (SELECT COUNT(*) FROM TASKS T
         WHERE T.BID_CASE_ID = B.BID_CASE_ID AND T.STATUS = #{approvedStatus}
           AND T.TEAM IN
#{t}
       ) = #{teamCount}
   AND NOT EXISTS (SELECT 1 FROM TASKS D WHERE D.BID_CASE_ID = B.BID_CASE_ID AND D.TEAM = #{designerTeam})
 ORDER BY I.NAME_KO, B.BID_CASE_ID
